import { IconActionButton } from '../IconActionButton';
import { ExperimentalIcon } from '../ExperimentalIcon';
import { CalendarDatePicker } from '../CalendarDatePicker';
import { TimeClockPicker } from '../TimeClockPicker';
import { addCivilDays, resolveCalendarWallTime, todayCivilDate } from '../calendar-context';
import { calendarMonthRange, formatCalendarDateValue, formatCalendarMonthValue } from '../calendar-data';
import { editPhysisRecord, newPhysisRecord, physisNumber, physisRecords, type PhysisFeatureProps, type PhysisRecord } from './types';
import { STARTER_EXERCISES, exerciseDisplayName, TrainingCreationDrafts, trainingDraftIsConfirmed, addExercise, applyVersionFrom, assignProgram, blankSet, comparableKey, completionScore, copyDay, copyExercise, copyMeso, copyMicro, estimatedOneRepMax, finishSession, newCycleDay, newMesocycle, newMicrocycle, newProgram, nextScheduled, pauseSession, previewMove, previousComparable, programDuration, progressionSuggestion, restSecondsRemaining, plannedWorkoutError, startPlannedSession, plannedTimer, scheduleStatus, sessionSummary, setCanComplete, setVolume, trainingDistanceFromKm, trainingDistanceToKm, trainingWeightFromKg, trainingWeightToKg, validateTrainingRecord, type CycleDay, type ExerciseChoice, type ExerciseDefinition, type ProgramVersion, type ScheduledWorkout, type TrainingAssignment, type TrainingExercise, type TrainingProgram, type TrainingSession, type TrainingSet, type WeightMode } from './training-domain';
