const clone = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T;
const tr = (en: boolean, ru: string, english: string) => en ? english : ru;
const shortNumber = (n: number) => Number(n.toFixed(2)).toLocaleString();
function useAction() {
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const running = useRef(false);
  const run = async (action: () => Promise<void>) => { if (running.current) return; running.current = true; setBusy(true); setError(''); try { await action(); } catch (e) { setError(e instanceof Error ? e.message : 'Не удалось сохранить. Повторите действие.'); } finally { running.current = false; setBusy(false); } };
  return { error, busy, run, setError };
}
function ErrorMessage({ error }: { error: string }) { return error ? <p className="physis-warning" role="alert">{error}</p> : null; }
function NumberField({ label, value, onChange, max = 10000, min = 0, integer = false }: { label: string; value: number | null; onChange: (v: number | null) => void; max?: number; min?: number; integer?: boolean }) {
  const [raw, setRaw] = useState<string | null>(null);
  const displayed = raw ?? (value === null ? '' : String(Number(value.toFixed(4))));
  const parsed = physisNumber(displayed, min, max);
  const invalid = displayed !== '' && (parsed === null || integer && !Number.isInteger(parsed));
  return <label>{label}<input inputMode={integer ? 'numeric' : 'decimal'} value={displayed} aria-invalid={invalid || undefined} onChange={e => { setRaw(e.target.value); const next = physisNumber(e.target.value, min, max); onChange(integer && !Number.isInteger(next) ? null : next); }} onBlur={() => { if (!invalid) setRaw(null); }} />{invalid && <span className="physis-warning">{min}–{max}</span>}</label>;
}
function BenchAngleField({ definition, en, onChange }: { definition: ExerciseDefinition; en: boolean; onChange: (value: ExerciseDefinition) => void }) {
  if (definition.benchAngleDegrees === undefined && !['genesis:incline-bench', 'genesis:incline-barbell-bench'].includes(definition.catalogId ?? '')) return null;
  return <label>{tr(en, 'Угол скамьи', 'Bench angle')}<select value={definition.benchAngleDegrees ?? ''} onChange={event => onChange({ ...definition, benchAngleDegrees: Number(event.target.value) })}><option value="" disabled>{tr(en, 'Укажите угол', 'Choose angle')}</option>{Array.from({ length: 18 }, (_, i) => i * 5).map(angle => <option key={angle} value={angle}>{angle}°</option>)}</select></label>;
}
function Reorder({ index, length, onMove, label }: { index: number; length: number; onMove: (delta: number) => void; label: string }) {
  return <span className="physis-actions physis-training-order"><button type="button" aria-label={`${label}: ↑`} title={`${label}: ↑`} disabled={index === 0} onClick={() => onMove(-1)}><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true"><path d="m6 14 6-6 6 6M12 8v12" /></svg></button><button type="button" aria-label={`${label}: ↓`} title={`${label}: ↓`} disabled={index === length - 1} onClick={() => onMove(1)}><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true"><path d="m6 10 6 6 6-6M12 16V4" /></svg></button></span>;
}
function reorder<T>(array: T[], index: number, delta: number): T[] { const result = [...array]; [result[index], result[index + delta]] = [result[index + delta], result[index]]; return result; }
const weightNames = (en: boolean): Record<WeightMode, string> => ({ total: tr(en, 'Общий вес', 'Total weight'), 'per-hand': tr(en, 'Вес одной гантели', 'One dumbbell'), 'per-side': tr(en, 'Вес на сторону', 'Weight per side'), bodyweight: tr(en, 'Дополнительный вес', 'Added load'), assisted: tr(en, 'Противовес', 'Assistance') });
const statusName = (status: string, en: boolean) => ({ rest: tr(en, 'Отдых', 'Rest'), planned: tr(en, 'Запланировано', 'Planned'), moved: tr(en, 'Перенесено', 'Moved'), skipped: tr(en, 'Пропущено', 'Skipped'), active: tr(en, 'Выполняется', 'In progress'), paused: tr(en, 'Приостановлено', 'Paused'), completed: tr(en, 'Выполнено', 'Completed'), partial: tr(en, 'Частично', 'Partial') }[status] || status);
function choicesFor(props: PhysisFeatureProps): ExerciseChoice[] {
  const personal = physisRecords<ExerciseDefinition>(props.store, 'exercise').map(r => ({ id: r.id, data: r.data, personal: true }));
  return [...STARTER_EXERCISES.filter(e => !personal.some(p => p.data.catalogId === e.id)), ...personal];
}
function ExerciseSelect({ choices, en, onSelect, label }: { choices: ExerciseChoice[]; en: boolean; onSelect: (choice: ExerciseChoice) => void; label?: string }) {
  const [search, setSearch] = useState('');
  const [selected, setSelected] = useState('');
  const shown = choices.filter(e => `${e.data.name} ${e.data.nameEn} ${e.data.aliases.join(' ')}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
  return <div className="physis-training-add physis-form"><label>{tr(en, 'Найти упражнение', 'Find exercise')}<input type="search" value={search} onChange={e => setSearch(e.target.value)} /></label><label>{tr(en, 'Упражнение', 'Exercise')}<select value={selected} onChange={e => setSelected(e.target.value)}><option value="">{tr(en, 'Выберите упражнение', 'Choose exercise')}</option>{shown.map(ex => <option key={ex.id} value={ex.id}>{en ? ex.data.nameEn || ex.data.name : ex.data.name}</option>)}</select></label><button type="button" disabled={!shown.some(e => e.id === selected)} onClick={() => { const found = shown.find(e => e.id === selected); if (found) { onSelect(found); setSelected(''); } }}>{label || tr(en, 'Добавить упражнение', 'Add exercise')}</button></div>;
}

function SetFields({ exercise, set, onChange, en, weightUnit, distanceUnit, plan = false }: { exercise: ExerciseDefinition; set: TrainingSet; onChange: (s: TrainingSet) => void; en: boolean; weightUnit: 'kg' | 'lb'; distanceUnit: 'km' | 'mi'; plan?: boolean }) {
  return <div className="physis-training-set-fields">
    <label>{tr(en, 'Тип подхода', 'Set type')}<select value={set.kind} onChange={e => onChange({ ...set, kind: e.target.value as TrainingSet['kind'] })}><option value="work">{tr(en, 'Рабочий', 'Work')}</option><option value="warmup">{tr(en, 'Разминка', 'Warm-up')}</option></select></label>
    {exercise.metric === 'strength' && <><NumberField key={weightUnit} label={`${weightNames(en)[exercise.weightMode]} (${weightUnit})`} value={set.weightKg === null ? null : trainingWeightFromKg(set.weightKg, weightUnit)} max={trainingWeightFromKg(10000, weightUnit)} onChange={value => onChange({ ...set, weightKg: value === null ? null : trainingWeightToKg(value, weightUnit) })} /><NumberField label={plan ? tr(en, 'Повторы от', 'Reps from') : tr(en, 'Повторы', 'Reps')} integer value={set.reps} max={10000} onChange={reps => onChange({ ...set, reps })} /></>}
    {(plan || exercise.metric === 'time' || exercise.metric === 'distance') && <NumberField label={tr(en, 'Время (сек)', 'Time (seconds)')} value={set.seconds} max={604800} onChange={seconds => onChange({ ...set, seconds })} />}
    {exercise.metric === 'distance' && <NumberField key={distanceUnit} label={`${tr(en, 'Дистанция', 'Distance')} (${distanceUnit})`} value={set.distanceKm === null ? null : trainingDistanceFromKm(set.distanceKm, distanceUnit)} max={trainingDistanceFromKm(10000, distanceUnit)} onChange={value => onChange({ ...set, distanceKm: value === null ? null : trainingDistanceToKm(value, distanceUnit) })} />}
    <details className="physis-training-set-extra"><summary>{tr(en, 'Диапазон, отдых, усилие', 'Range, rest, effort')}</summary><div className="physis-form">
      {exercise.metric === 'strength' && <NumberField label={tr(en, 'Верхняя граница повторов', 'Upper rep target')} integer value={set.repsMax} onChange={repsMax => onChange({ ...set, repsMax })} />}
      <NumberField label={tr(en, 'Отдых (сек)', 'Rest (seconds)')} value={set.restSeconds} max={86400} onChange={restSeconds => onChange({ ...set, restSeconds: restSeconds ?? 0 })} />
      <NumberField label="RPE (0–10)" value={set.rpe} max={10} onChange={rpe => onChange({ ...set, rpe })} /><NumberField label="RIR" value={set.rir} max={100} onChange={rir => onChange({ ...set, rir })} />
      {(exercise.unilateral || ['per-hand', 'per-side'].includes(exercise.weightMode)) && <label>{tr(en, 'Сторона', 'Side')}<select value={set.side} onChange={e => onChange({ ...set, side: e.target.value as TrainingSet['side'] })}><option value="both">{tr(en, 'Обе (повторы на каждую)', 'Both (reps per side)')}</option><option value="left">{tr(en, 'Левая', 'Left')}</option><option value="right">{tr(en, 'Правая', 'Right')}</option></select></label>}
    </div></details>
  </div>;
}

function useSessionDraft(record: PhysisRecord<TrainingSession>, store: PhysisFeatureProps['store']) {
  const { save } = store;
  const [draft, setDraft] = useState(record);
  const [state, setState] = useState<'saved' | 'saving' | 'error'>('saved');
  const [error, setError] = useState('');
  const pending = useRef<PhysisRecord<TrainingSession> | null>(null);
  const saving = useRef<Promise<boolean> | null>(null);
  const latest = useRef(record);
  const enqueue = useCallback((next: PhysisRecord<TrainingSession>): Promise<boolean> => {
    pending.current = next;
    setState('saving'); setError('');
    const operation = async () => {
      // save synchronously registers the plaintext in the vault's memory queue before
      // its first await. The store serializes encrypted requests and owns retries.
      // Navigation immediately after input therefore cannot drop a debounce-only draft.
      try { await save(next); } catch (e) {
        if (pending.current === next) { setState('error'); setError(e instanceof Error ? e.message : 'Не сохранено. Проверьте соединение и повторите.'); }
        return false;
      }
      if (pending.current === next) { pending.current = null; setState('saved'); }
      return true;
    };
    const promise = operation(); saving.current = promise;
    void promise.then(() => { if (saving.current === promise) saving.current = null; });
    return promise;
  }, [save]);
  const flush = useCallback(async (force = false): Promise<boolean> => {
    if (saving.current) { const succeeded = await saving.current; if (succeeded && !force) return true; }
    const next = pending.current ?? (force ? latest.current : null);
    return next ? enqueue(next) : true;
  }, [enqueue]);
  const change = (data: TrainingSession) => {
    const next = editPhysisRecord(draft, { ...data, editedAt: draft.data.endedAt ? new Date().toISOString() : data.editedAt });
    latest.current = next; setDraft(next); void enqueue(next);
  };
  const confirmed = trainingDraftIsConfirmed(draft, store);
  useEffect(() => {
    if (confirmed && trainingDraftIsConfirmed(latest.current, store)) pending.current = null;
  }, [confirmed, store]);
  useEffect(() => {
    const leave = (event: BeforeUnloadEvent) => { if (pending.current) { event.preventDefault(); event.returnValue = ''; } };
    const retry = () => { if (pending.current) void flush(); };
    window.addEventListener('beforeunload', leave); window.addEventListener('online', retry);
    return () => {
      window.removeEventListener('beforeunload', leave); window.removeEventListener('online', retry);
    };
  }, [flush]);
  return { draft, state: confirmed ? 'saved' as const : store.status === 'saving' ? 'saving' as const : state, error: confirmed || store.status === 'saving' ? '' : error, confirmed, change, flush };
}

function SessionEditor({ record, props, onClose }: { record: PhysisRecord<TrainingSession>; props: PhysisFeatureProps; onClose: () => void }) {
  const en = props.language === 'en';
  const { draft, state, error, confirmed, change, flush } = useSessionDraft(record, props.store);
  const [now, setNow] = useState(() => Date.now());
  const [editingHistory, setEditingHistory] = useState(!!record.data.endedAt && record.data.startedAt === record.data.endedAt);
  const [notice, setNotice] = useState('');
  const action = useAction();
  const session = draft.data;
  const summary = sessionSummary(session, now);
  const finished = !!session.endedAt;
  const canEdit = !finished || editingHistory;
  const canEditStructure = canEdit && !session.assignmentId;
  const timer = plannedTimer(session, now);
  const clock = (seconds: number) => `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
  const saveFailed = state === 'error' || ['offline', 'error', 'conflict'].includes(props.store.status);
  const saveConfirmed = confirmed;
  const choices = choicesFor(props);
  const sessions = physisRecords<TrainingSession>(props.store, 'session');
  const programs = physisRecords<TrainingProgram>(props.store, 'program');
  const program = programs.find(p => p.id === session.programId);
  const templateDrafts = useRef(new TrainingCreationDrafts<TrainingProgram>()).current;
  const updateExercise = (index: number, exercise: TrainingExercise) => change({ ...session, exercises: session.exercises.map((ex, i) => i === index ? exercise : ex) });
  useEffect(() => { if (session.status !== 'active') return; const interval = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(interval); }, [session.status]);
  const saveTemplate = (newVersion: boolean) => action.run(async () => {
    if (!await flush(true)) return;
    const intent = newVersion && program ? `version:${program.id}` : 'new-program';
    await templateDrafts.save(intent, () => {
      const exercises = session.exercises.map(copyExercise);
      if (newVersion && program) {
        const latest = clone(program.data.versions[program.data.versions.length - 1]);
        latest.id = crypto.randomUUID(); latest.version += 1; latest.createdAt = new Date().toISOString();
        const assignment = physisRecords<TrainingAssignment>(props.store, 'assignment').find(a => a.id === session.assignmentId);
        const originalDayId = assignment?.data.scheduled.find(s => s.id === session.scheduledId)?.snapshot.id;
        let replaced = false;
        latest.mesocycles = latest.mesocycles.map(m => ({ ...m, microcycles: m.microcycles.map(c => ({ ...c, days: c.days.map(d => { if (d.id !== originalDayId) return d; replaced = true; return { ...d, exercises, name: session.name }; }) })) }));
        if (!replaced) latest.mesocycles[0].microcycles[0].days.push({ ...newCycleDay(), name: session.name, exercises });
        const next = editPhysisRecord(program, { ...program.data, versions: [...program.data.versions, latest] });
        if (!validateTrainingRecord(next)) throw new Error(tr(en, 'Версия превышает допустимый размер.', 'The version exceeds the supported size.'));
        return next;
      }
      const next = newProgram(session.name || tr(en, 'Моя тренировка', 'My workout'));
      next.versions[0].mesocycles[0].microcycles[0].days = [{ ...newCycleDay(), name: session.name, exercises }];
      return newPhysisRecord('program', next);
    }, props.store);
    setNotice(tr(en, 'Шаблон сохранён отдельно. Назначения и история сохранены.', 'Template saved separately. Assignments and history are preserved.'));
  });
  return <section className="physis-panel physis-training-session" aria-label={tr(en, 'Журнал тренировки', 'Workout log')}>
    <div className="physis-row"><h2>{session.name || tr(en, 'Тренировка', 'Workout')}</h2><button type="button" onClick={() => { void action.run(async () => { if (await flush(true)) onClose(); }); }}>{tr(en, 'Сохранить и закрыть', 'Save and close')}</button></div>
    <p className="physis-muted">{formatCalendarDateValue(session.localDay, props.settings.calendarMode, true, props.context)} · {session.timeZone} · {statusName(session.status, en)}</p>
    <p role="status" className={`physis-status ${saveFailed ? 'physis-warning' : ''}`}>{saveConfirmed ? tr(en, 'Сохранено на сервере', 'Saved on server') : saveFailed ? tr(en, 'Не сохранено — оставьте вкладку открытой', 'Unsaved — keep this tab open') : tr(en, 'Сохраняется…', 'Saving…')}{session.editedAt && ` · ${tr(en, 'Исправлено', 'Edited')} ${new Date(session.editedAt).toLocaleString()}`}</p>
    <ErrorMessage error={error || props.store.error || action.error} />{saveFailed && <button type="button" onClick={() => { void flush(true); }}>{tr(en, 'Повторить сохранение', 'Retry saving')}</button>}
    {notice && <p role="status">{notice}</p>}
    {finished && <div className="physis-training-result"><h3>{tr(en, 'Результат', 'Result')}</h3><p>{summary.completedSets}/{summary.sets} {tr(en, 'подходов', 'sets')} · {Math.round(summary.seconds / 60)} {tr(en, 'мин', 'min')} · {shortNumber(trainingWeightFromKg(summary.volumeKg, props.settings.weightUnit))} {props.settings.weightUnit}·{tr(en, 'повторов внешнего веса', 'reps external load')}{summary.distanceKm > 0 && <> · {shortNumber(trainingDistanceFromKm(summary.distanceKm, props.settings.distanceUnit))} {props.settings.distanceUnit}</>}</p><p className="physis-muted">{tr(en, 'Масса тела и противовес исключены из объёма. Разминка не включена.', 'Body mass, assistance and warm-up sets are excluded from load volume.')}</p><div className="physis-actions"><button type="button" onClick={() => setEditingHistory(!editingHistory)}>{editingHistory ? tr(en, 'Закончить исправление', 'Finish correction') : tr(en, 'Исправить факт', 'Correct this record')}</button><button type="button" disabled={action.busy} onClick={() => { void saveTemplate(false); }}>{tr(en, 'Сохранить как программу', 'Save as a program')}</button>{program && <button type="button" disabled={action.busy} onClick={() => { void saveTemplate(true); }}>{tr(en, 'Новая версия программы', 'New program version')}</button>}</div></div>}
    {canEdit && <div className="physis-form"><label>{tr(en, 'Название', 'Name')}<input maxLength={500} value={session.name} onChange={e => change({ ...session, name: e.target.value })} /></label><label>{tr(en, 'День факта', 'Recorded day')}<CalendarDatePicker value={session.localDay} mode={props.settings.inputCalendarMode} calculationContext={props.context} ariaLabel={tr(en, 'День факта тренировки', 'Workout recorded day')} onChange={localDay => { if (localDay) change({ ...session, localDay }); }} /></label>{finished && <NumberField label={tr(en, 'Длительность (мин)', 'Duration (min)')} value={summary.seconds / 60} max={10080} onChange={minutes => { if (minutes !== null) change({ ...session, endedAt: new Date(Date.parse(session.startedAt) + (minutes * 60 + session.pausedSeconds) * 1000).toISOString() }); }} />}</div>}
    {finished && canEdit && <label>{tr(en, 'Время начала (в часовом поясе записи)', 'Start time (recorded time zone)')}<TimeClockPicker value={new Intl.DateTimeFormat('en-GB', { timeZone: session.timeZone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(session.startedAt))} ariaLabel={tr(en, 'Время начала тренировки', 'Workout start time')} onChange={time => { try { const resolved = resolveCalendarWallTime(session.localDay, time, session.timeZone); const duration = Date.parse(session.endedAt!) - Date.parse(session.startedAt); change({ ...session, startedAt: resolved.instant.toISOString(), endedAt: new Date(resolved.instant.getTime() + duration).toISOString() }); if (resolved.adjustment !== 'exact') setNotice(tr(en, 'Время скорректировано существующим правилом Genesis для перехода летнего времени.', 'Time adjusted by the existing Genesis daylight-saving rule.')); } catch { action.setError(tr(en, 'Проверьте дату и время.', 'Check date and time.')); } }} /></label>}
    {timer && !finished && <section className="physis-training-plan-timer" aria-label={tr(en, 'Таймер по плану', 'Planned workout timer')}>
      <div className="physis-training-timer"><strong role="timer" aria-live="off">{clock(timer.remaining)}</strong><div><h3>{timer.phase === 'done' ? tr(en, 'Плановое время завершено', 'Planned time finished') : timer.phase === 'rest' ? tr(en, 'Отдых', 'Rest') : tr(en, 'Выполнение подхода', 'Work interval')}</h3><p>{session.exercises.find(ex => ex.id === timer.step.exerciseId)?.snapshot.name} · {tr(en, 'Подход', 'Set')} {timer.index + 1}/{session.timerPlan!.length}</p></div></div>
      <p>{session.status === 'paused' ? tr(en, 'Таймер на паузе', 'Timer paused') : tr(en, 'До конца плана', 'Plan remaining')}: {clock(timer.totalRemaining)} / {clock(timer.total)}</p>
      <progress max={timer.total} value={timer.total - timer.totalRemaining} aria-label={tr(en, 'Ход тренировки по плану', 'Planned workout progress')} />
      <p className="physis-muted">{timer.phase === 'done' ? tr(en, 'Отметьте фактически выполненные подходы и завершите тренировку.', 'Mark the sets you actually completed and finish the workout.') : tr(en, 'Работа и отдых переключаются по времени из плана. Выполнение подходов отмечайте отдельно.', 'Work and rest follow the saved plan. Mark actual sets separately.')}</p>
    </section>}
    {!!session.restEndAt && !timer && <div className="physis-training-timer" role="timer" aria-label={tr(en, 'Таймер отдыха', 'Rest timer')}><strong>{restSecondsRemaining(session.restEndAt, now) ? `${Math.floor(restSecondsRemaining(session.restEndAt, now) / 60)}:${String(restSecondsRemaining(session.restEndAt, now) % 60).padStart(2, '0')}` : tr(en, 'Отдых завершён', 'Rest finished')}</strong><button type="button" onClick={() => change({ ...session, restEndAt: null })}>{tr(en, 'Убрать таймер', 'Dismiss timer')}</button></div>}
    {!session.exercises.length && <p className="physis-empty">{tr(en, 'Добавьте первое упражнение. Плановые значения станут фактом только после отметки подхода.', 'Add your first exercise. Planned values become actual only when you mark the set done.')}</p>}
    {session.exercises.map((exercise, exIndex) => {
      const previous = previousComparable(exercise, draft.id, sessions, session.startedAt);
      const lastSet = previous?.sets.filter(s => s.completed && s.kind === 'work').at(-1);
      const suggestion = program ? progressionSuggestion(exercise, program.data.versions.find(v => v.id === session.programVersionId)?.progression ?? { mode: 'manual', stepKg: 0 }) : null;
      return <section key={exercise.id} className="physis-training-exercise">
        <div className="physis-row"><h3>{en ? exercise.snapshot.nameEn || exercise.snapshot.name : exercise.snapshot.name}</h3>{canEditStructure && <Reorder label={tr(en, 'Переставить упражнение', 'Reorder exercise')} index={exIndex} length={session.exercises.length} onMove={delta => change({ ...session, exercises: reorder(session.exercises, exIndex, delta) })} />}</div>
        <ExerciseDemoButton exerciseId={exercise.exerciseId} definition={exercise.snapshot} en={en} />
        <p className="physis-muted">{weightNames(en)[exercise.snapshot.weightMode]}{exercise.snapshot.weightMode === 'bodyweight' && ` · ${tr(en, 'масса тела не входит в вес', 'body mass excluded')}`}{exercise.snapshot.weightMode === 'assisted' && ` · ${tr(en, 'больше противовес — меньше нагрузка', 'more assistance means less load')}`}</p>
        {lastSet && <p>{tr(en, 'В прошлый раз', 'Previous comparable result')}: {lastSet.weightKg !== null && `${shortNumber(trainingWeightFromKg(lastSet.weightKg, props.settings.weightUnit))} ${props.settings.weightUnit} × `}{lastSet.reps ?? ''}{lastSet.seconds !== null && ` ${lastSet.seconds} ${tr(en, 'сек', 's')}`}{lastSet.distanceKm !== null && ` ${shortNumber(trainingDistanceFromKm(lastSet.distanceKm, props.settings.distanceUnit))} ${props.settings.distanceUnit}`}</p>}
        {!!exercise.group && <p>{tr(en, 'Суперсет / круг', 'Superset / circuit')}: {exercise.group}</p>}
        {exercise.sets.map((set, setIndex) => <div key={set.id} className={`physis-training-set ${set.completed ? 'is-complete' : ''}`}>
          <div className="physis-row"><strong>{tr(en, 'Подход', 'Set')} {setIndex + 1} · {set.completed ? tr(en, 'Выполнен', 'Done') : tr(en, 'Не выполнен', 'Not done')}</strong>{canEditStructure && <button type="button" aria-label={tr(en, `Удалить подход ${setIndex + 1}`, `Remove set ${setIndex + 1}`)} onClick={() => updateExercise(exIndex, { ...exercise, sets: exercise.sets.filter(s => s.id !== set.id) })}>{tr(en, 'Удалить', 'Remove')}</button>}</div>
          {canEdit ? <><SetFields exercise={exercise.snapshot} set={set} en={en} weightUnit={props.settings.weightUnit} distanceUnit={props.settings.distanceUnit} onChange={value => updateExercise(exIndex, { ...exercise, sets: exercise.sets.map(s => s.id === set.id ? value : s) })} /><button type="button" className={set.completed ? '' : 'physis-primary'} aria-pressed={set.completed} disabled={session.status === 'paused' || (!set.completed && !setCanComplete(exercise.snapshot, set))} onClick={() => {
            const completed = !set.completed;
            const exercises = session.exercises.map((ex, i) => i === exIndex ? { ...ex, sets: ex.sets.map(s => s.id === set.id ? { ...s, completed } : s) } : ex);
            change({ ...session, exercises, restEndAt: completed && !finished && !timer && set.restSeconds > 0 ? new Date(Date.now() + set.restSeconds * 1000).toISOString() : session.restEndAt });
          }}>{set.completed ? tr(en, 'Отменить отметку', 'Undo completion') : tr(en, 'Выполнено', 'Mark done')}</button></> : <p>{set.weightKg !== null && `${shortNumber(trainingWeightFromKg(set.weightKg, props.settings.weightUnit))} ${props.settings.weightUnit} · `}{set.reps !== null && `${set.reps} ${tr(en, 'повт.', 'reps')} `}{set.seconds !== null && `${set.seconds} s `}{set.distanceKm !== null && `${shortNumber(trainingDistanceFromKm(set.distanceKm, props.settings.distanceUnit))} ${props.settings.distanceUnit} `}{set.rpe !== null && `RPE ${set.rpe} `}{set.rir !== null && `RIR ${set.rir}`}</p>}
        </div>)}
        {canEditStructure && <div className="physis-actions"><button type="button" onClick={() => updateExercise(exIndex, { ...exercise, sets: [...exercise.sets, blankSet(props.settings.restSeconds)] })}>{tr(en, 'Добавить подход', 'Add set')}</button><button type="button" disabled={!exercise.sets.length} onClick={() => updateExercise(exIndex, { ...exercise, sets: [...exercise.sets, { ...exercise.sets[exercise.sets.length - 1], id: crypto.randomUUID(), completed: false }] })}>{tr(en, 'Копировать предыдущий', 'Copy previous')}</button></div>}
        {canEditStructure && <details><summary>{tr(en, 'Параметры упражнения', 'Exercise options')}</summary><div className="physis-form"><label>{tr(en, 'Группа суперсета / круга', 'Superset / circuit group')}<input maxLength={500} value={exercise.group} onChange={e => updateExercise(exIndex, { ...exercise, group: e.target.value })} /></label><label>{tr(en, 'Заметка', 'Note')}<textarea value={exercise.notes} onChange={e => updateExercise(exIndex, { ...exercise, notes: e.target.value })} /></label><label>{tr(en, 'Учёт веса', 'Weight convention')}<select value={exercise.snapshot.weightMode} onChange={e => updateExercise(exIndex, { ...exercise, snapshot: { ...exercise.snapshot, weightMode: e.target.value as WeightMode } })}>{Object.entries(weightNames(en)).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div><ExerciseSelect choices={choices} en={en} label={tr(en, 'Заменить упражнение', 'Replace exercise')} onSelect={choice => updateExercise(exIndex, addExercise(choice, props.settings.restSeconds))} /><button type="button" onClick={() => change({ ...session, exercises: session.exercises.filter(ex => ex.id !== exercise.id) })}>{tr(en, 'Удалить упражнение из занятия', 'Remove exercise from session')}</button></details>}
        {finished && suggestion !== null && <p className="physis-status">{tr(en, 'Рекомендация для следующего плана', 'Suggestion for next plan')}: {shortNumber(trainingWeightFromKg(suggestion, props.settings.weightUnit))} {props.settings.weightUnit}. {tr(en, 'Примените вручную в новой версии программы после оценки самочувствия. История не изменена.', 'Apply manually in a new program version after reviewing readiness. History remains unchanged.')}</p>}
      </section>;
    })}
    {canEdit && <>{canEditStructure && <ExerciseSelect choices={choices} en={en} onSelect={choice => change({ ...session, exercises: [...session.exercises, addExercise(choice, props.settings.restSeconds)] })} />}<label>{tr(en, 'Заметка о тренировке', 'Workout note')}<textarea value={session.notes} onChange={e => change({ ...session, notes: e.target.value })} /></label></>}
    {!finished && <div className="physis-actions physis-training-primary-actions"><button type="button" onClick={() => change(pauseSession(session))}>{session.status === 'paused' ? tr(en, 'Продолжить', 'Resume') : tr(en, 'Пауза', 'Pause')}</button><button type="button" className="physis-primary" onClick={() => change(finishSession(session))}>{summary.completedSets < summary.sets || !summary.sets ? tr(en, 'Завершить частично', 'Finish partial') : tr(en, 'Завершить тренировку', 'Finish workout')}</button></div>}
    {finished && editingHistory && <button type="button" className="physis-primary" onClick={() => { const sets = session.exercises.flatMap(e => e.sets); change({ ...session, status: sets.length > 0 && sets.every(s => s.completed) ? 'completed' : 'partial' }); void flush(); setEditingHistory(false); }}>{tr(en, 'Сохранить исправление', 'Save correction')}</button>}
  </section>;
}

function ExerciseCatalog(props: PhysisFeatureProps) {
  const en = props.language === 'en'; const action = useAction();
  const [query, setQuery] = useState(''); const [muscle, setMuscle] = useState(''); const [movement, setMovement] = useState(''); const [equipment, setEquipment] = useState(''); const [environment, setEnvironment] = useState(''); const [favorite, setFavorite] = useState(false);
  const [editing, setEditing] = useState<PhysisRecord<ExerciseDefinition> | null>(null);
  const choices = choicesFor(props);
  const visible = choices.filter(ex => `${ex.data.name} ${ex.data.nameEn} ${ex.data.aliases.join(' ')}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()) && (!muscle || ex.data.muscles === muscle) && (!movement || ex.data.movement === movement) && (!equipment || ex.data.equipment === equipment) && (!environment || ex.data.environment === environment) && (!favorite || ex.data.favorite));
  const create = (choice?: ExerciseChoice) => setEditing(newPhysisRecord('exercise', choice ? { ...clone(choice.data), catalogId: undefined, name: `${choice.data.name} — ${tr(en, 'копия', 'copy')}` } : { name: '', nameEn: '', aliases: [], muscles: '', movement: '', equipment: '', environment: '', technique: '', mistakes: '', variants: '', source: tr(en, 'Личная запись', 'Personal entry'), metric: 'strength', weightMode: 'total', unilateral: false, favorite: false, notes: '' }));
  const toggleFavorite = (choice: ExerciseChoice) => action.run(async () => { const existing = physisRecords<ExerciseDefinition>(props.store, 'exercise').find(r => r.id === choice.id || r.data.catalogId === choice.id); await props.store.save(existing ? editPhysisRecord(existing, { ...existing.data, favorite: !existing.data.favorite }) : newPhysisRecord('exercise', { ...choice.data, favorite: !choice.data.favorite })); });
  return <section className="physis-panel"><div className="physis-row physis-exercise-heading"><h2>{tr(en, 'Справочник упражнений', 'Exercise library')}</h2><button type="button" className="physis-primary" onClick={() => create()}>{tr(en, 'Своё упражнение', 'New exercise')}</button></div><p className="physis-muted">{tr(en, 'Откройте упражнение, чтобы увидеть движение, работающие мышцы и разбор техники. Личные записи и избранное зашифрованы.', 'Open an exercise to see the movement, working muscles and technique. Personal entries and favorites are encrypted.')}</p><ErrorMessage error={action.error} />
    {editing && <form className="physis-training-editor" onSubmit={e => { e.preventDefault(); void action.run(async () => { if (!editing.data.name.trim() || !validateTrainingRecord(editing)) throw new Error(tr(en, 'Проверьте название и параметры.', 'Check name and parameters.')); await props.store.save(editing); setEditing(null); }); }}><h3>{tr(en, 'Личное упражнение', 'Personal exercise')}</h3><div className="physis-form">{(['name', 'nameEn', 'muscles', 'movement', 'equipment', 'environment'] as const).map((key, i) => <label key={key}>{[tr(en, 'Название', 'Name'), tr(en, 'Название на английском', 'English name'), tr(en, 'Мышцы', 'Muscles'), tr(en, 'Движение', 'Movement'), tr(en, 'Оборудование', 'Equipment'), tr(en, 'Условия', 'Environment')][i]}<input required={key === 'name'} maxLength={500} value={editing.data[key]} onChange={e => setEditing(editPhysisRecord(editing, { ...editing.data, [key]: e.target.value }))} /></label>)}<label>{tr(en, 'Синонимы (через запятую)', 'Aliases (comma separated)')}<input value={editing.data.aliases.join(', ')} onChange={e => setEditing(editPhysisRecord(editing, { ...editing.data, aliases: e.target.value.split(',').map(s => s.trim()) }))} /></label><label>{tr(en, 'Измерение', 'Measurement')}<select value={editing.data.metric} onChange={e => setEditing(editPhysisRecord(editing, { ...editing.data, metric: e.target.value as ExerciseDefinition['metric'] }))}><option value="strength">{tr(en, 'Вес / повторения', 'Weight / reps')}</option><option value="time">{tr(en, 'Время', 'Time')}</option><option value="distance">{tr(en, 'Дистанция / время', 'Distance / time')}</option></select></label><label>{tr(en, 'Учёт веса', 'Weight convention')}<select value={editing.data.weightMode} onChange={e => setEditing(editPhysisRecord(editing, { ...editing.data, weightMode: e.target.value as WeightMode }))}>{Object.entries(weightNames(en)).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div><BenchAngleField en={en} definition={editing.data} onChange={data => setEditing(editPhysisRecord(editing, data))} /><label><input type="checkbox" checked={editing.data.unilateral} onChange={e => setEditing(editPhysisRecord(editing, { ...editing.data, unilateral: e.target.checked }))} />{tr(en, 'Одностороннее упражнение', 'Unilateral exercise')}</label>{(['technique', 'mistakes', 'variants', 'source', 'notes'] as const).map((key, i) => <label key={key}>{[tr(en, 'Техника', 'Technique'), tr(en, 'Ошибки', 'Common errors'), tr(en, 'Варианты', 'Variations'), tr(en, 'Источник / лицензия', 'Source / license'), tr(en, 'Личные заметки', 'Personal notes')][i]}<textarea maxLength={20000} value={editing.data[key]} onChange={e => setEditing(editPhysisRecord(editing, { ...editing.data, [key]: e.target.value }))} /></label>)}<div className="physis-actions"><button type="submit" className="physis-primary" disabled={action.busy}>{tr(en, 'Сохранить упражнение', 'Save exercise')}</button><button type="button" onClick={() => setEditing(null)}>{tr(en, 'Отмена', 'Cancel')}</button></div></form>}
    <div className="physis-form"><label>{tr(en, 'Поиск RU / EN', 'Search RU / EN')}<input type="search" value={query} onChange={e => setQuery(e.target.value)} /></label>{([{ field: 'muscles', value: muscle, set: setMuscle, label: tr(en, 'Мышцы', 'Muscles') }, { field: 'movement', value: movement, set: setMovement, label: tr(en, 'Движение', 'Movement') }, { field: 'equipment', value: equipment, set: setEquipment, label: tr(en, 'Оборудование', 'Equipment') }, { field: 'environment', value: environment, set: setEnvironment, label: tr(en, 'Условия', 'Environment') }] as const).map(filter => <label key={filter.field}>{filter.label}<select value={filter.value} onChange={e => filter.set(e.target.value)}><option value="">{tr(en, 'Все', 'All')}</option>{[...new Set(choices.map(e => e.data[filter.field]).filter(Boolean))].map(value => <option key={value} value={value}>{exerciseTagLabel(value, en)}</option>)}</select></label>)}</div><label><input type="checkbox" checked={favorite} onChange={e => setFavorite(e.target.checked)} />{tr(en, 'Только избранное', 'Favorites only')}</label>
    {!visible.length && <p className="physis-empty">{tr(en, 'Ничего не найдено. Измените фильтры или добавьте своё упражнение.', 'No matches. Change filters or add your own exercise.')}</p>}
    <ExerciseGallery choices={visible} en={en} actions={(choice, close) => <><button type="button" disabled={action.busy} onClick={() => { void toggleFavorite(choice); }}>{choice.data.favorite ? tr(en, 'Убрать из избранного', 'Unfavorite') : tr(en, 'В избранное', 'Favorite')}</button><button type="button" onClick={() => { close(); create(choice); }}>{tr(en, 'Копировать', 'Copy')}</button><button type="button" onClick={() => { close(); const existing = physisRecords<ExerciseDefinition>(props.store, 'exercise').find(r => r.id === choice.id); setEditing(existing ?? newPhysisRecord('exercise', clone(choice.data))); }}>{tr(en, 'Личные заметки / правка', 'Personal notes / edit')}</button>{choice.personal && <button type="button" disabled={action.busy} onClick={() => { void action.run(async () => { await props.store.remove(choice.id); }); }}>{tr(en, 'Удалить из справочника', 'Remove from library')}</button>}</>} />
  </section>;
}

function DayEditor({ day, update, props }: { day: CycleDay; update: (day: CycleDay) => void; props: PhysisFeatureProps }) {
  const en = props.language === 'en';
  const choices = choicesFor(props);
  const updateExercise = (index: number, ex: TrainingExercise) => update({ ...day, exercises: day.exercises.map((item, i) => index === i ? ex : item) });
  return <div className="physis-training-editor"><div className="physis-form"><label>{tr(en, 'Название дня', 'Day name')}<input maxLength={500} value={day.name} onChange={e => update({ ...day, name: e.target.value })} /></label><label>{tr(en, 'Тип дня', 'Day type')}<select value={day.kind} onChange={e => update({ ...day, kind: e.target.value as CycleDay['kind'] })}><option value="workout">{tr(en, 'Тренировка', 'Workout')}</option><option value="rest">{tr(en, 'Отдых', 'Rest')}</option></select></label></div><label>{tr(en, 'Заметка дня', 'Day note')}<textarea value={day.notes} onChange={e => update({ ...day, notes: e.target.value })} /></label>
    {day.kind === 'workout' && <>{!day.exercises.length && <p className="physis-empty">{tr(en, 'Добавьте упражнения и плановые подходы этого дня.', 'Add exercises and planned sets for this day.')}</p>}{day.exercises.map((exercise, index) => <div key={exercise.id} className="physis-training-exercise"><div className="physis-row"><h4>{en ? exercise.snapshot.nameEn || exercise.snapshot.name : exercise.snapshot.name}</h4><Reorder index={index} length={day.exercises.length} label={tr(en, 'Переставить упражнение', 'Reorder exercise')} onMove={delta => update({ ...day, exercises: reorder(day.exercises, index, delta) })} /></div><BenchAngleField en={en} definition={exercise.snapshot} onChange={snapshot => updateExercise(index, { ...exercise, snapshot })} /><PercentLoadEditor exercise={exercise} onChange={value=>updateExercise(index,value)} props={props} /><label>{tr(en, 'Группа суперсета / круга', 'Superset / circuit group')}<input maxLength={500} value={exercise.group} onChange={e => updateExercise(index, { ...exercise, group: e.target.value })} /></label>{exercise.sets.map((set, si) => <div className="physis-training-set" key={set.id}><strong>{tr(en, 'Плановый подход', 'Planned set')} {si + 1}</strong><SetFields en={en} exercise={exercise.snapshot} set={set} weightUnit={props.settings.weightUnit} distanceUnit={props.settings.distanceUnit} plan onChange={value => updateExercise(index, { ...exercise, sets: exercise.sets.map(s => s.id === set.id ? { ...value, completed: false } : s) })} /><button type="button" onClick={() => updateExercise(index, { ...exercise, sets: exercise.sets.filter(s => s.id !== set.id) })}>{tr(en, 'Удалить подход', 'Remove set')}</button></div>)}<div className="physis-actions"><button type="button" onClick={() => updateExercise(index, { ...exercise, sets: [...exercise.sets, exercise.sets.length ? { ...exercise.sets.at(-1)!, id: crypto.randomUUID(), completed: false } : blankSet(props.settings.restSeconds)] })}>{tr(en, 'Добавить подход', 'Add set')}</button><button type="button" onClick={() => update({ ...day, exercises: day.exercises.filter(e => e.id !== exercise.id) })}>{tr(en, 'Удалить упражнение', 'Remove exercise')}</button></div></div>)}<ExerciseSelect choices={choices} en={en} onSelect={choice => update({ ...day, exercises: [...day.exercises, addExercise(choice, props.settings.restSeconds)] })} /></>}
  </div>;
}

function ProgramEditor({ record, props, onClose }: { record: PhysisRecord<TrainingProgram>; props: PhysisFeatureProps; onClose: () => void }) {
  const en = props.language === 'en'; const action = useAction();
  const [program, setProgram] = useState(clone(record.data));
  const [version, setVersion] = useState(clone(record.data.versions.at(-1)!));
  const [selectedDay, setSelectedDay] = useState<string | null>(version.mesocycles[0]?.microcycles[0]?.days[0]?.id ?? null);
  const [length, setLength] = useState<number | null>(8);
  const [isExisting] = useState(() => props.store.records.some(r => r.id === record.id));
  const [versionIdentity] = useState(() => ({ id: crypto.randomUUID(), createdAt: new Date().toISOString() }));
  const setDay = (id: string, value: CycleDay) => setVersion({ ...version, mesocycles: version.mesocycles.map(m => ({ ...m, microcycles: m.microcycles.map(c => ({ ...c, days: c.days.map(d => d.id === id ? value : d) })) })) });
  const selected = version.mesocycles.flatMap(m => m.microcycles.flatMap(c => c.days)).find(d => d.id === selectedDay);
  return <section className="physis-panel"><div className="physis-row"><h2>{isExisting ? tr(en, 'Новая версия программы', 'New program version') : tr(en, 'Конструктор программы', 'Program builder')}</h2><button type="button" onClick={onClose}>{tr(en, 'Закрыть без сохранения', 'Close without saving')}</button></div><p className="physis-muted">{tr(en, 'Достаточно одного микроцикла. Раскройте этапы для сложной периодизации. Программа и фактические тренировки сохраняются отдельно.', 'One microcycle is enough. Expand stages for advanced periodization. Programs and actual sessions are stored separately.')}</p><ErrorMessage error={action.error} /><form onSubmit={e => { e.preventDefault(); void action.run(async () => {
    if (!program.name.trim()) throw new Error(tr(en, 'Введите название программы.', 'Enter a program name.'));
    if (!programDuration(version) || programDuration(version) > 1098) throw new Error(tr(en, 'Продолжительность — от 1 до 1098 дней.', 'Duration must be between 1 and 1098 days.'));
    const snapshot = { ...clone(version), ...versionIdentity, version: isExisting ? record.data.versions.at(-1)!.version + 1 : 1, name: program.name };
    const updated = editPhysisRecord(record, { ...program, versions: isExisting ? [...record.data.versions, snapshot] : [snapshot] });
    if (!validateTrainingRecord(updated)) throw new Error(tr(en, 'Проверьте диапазоны повторов и размер программы.', 'Check rep ranges and program size.'));
    await props.store.save(updated); onClose();
  }); }}>
    <div className="physis-form"><label>{tr(en, 'Название / макроцикл', 'Name / macrocycle')}<input required maxLength={500} value={program.name} onChange={e => setProgram({ ...program, name: e.target.value })} /></label><label>{tr(en, 'Коллекция', 'Collection')}<select value={program.collection} onChange={e => setProgram({ ...program, collection: e.target.value as TrainingProgram['collection'] })}><option value="personal">{tr(en, 'Мои программы', 'My programs')}</option><option value="alchemy">{tr(en, 'Алхимический фитнес', 'Alchemical fitness')}</option></select></label><label>{tr(en, 'Общая цель', 'Overall goal')}<input value={version.goal} onChange={e => setVersion({ ...version, goal: e.target.value })} /></label></div>
    <details><summary>{tr(en, 'Описание и метаданные этапа', 'Description and stage metadata')}</summary><label>{tr(en, 'Описание', 'Description')}<textarea value={version.description} onChange={e => setVersion({ ...version, description: e.target.value })} /></label><div className="physis-form"><label>{tr(en, 'Авторский символ (текст)', 'Author symbol (text)')}<input value={version.symbol} onChange={e => setVersion({ ...version, symbol: e.target.value })} /></label><label>{tr(en, 'Теги через запятую', 'Comma-separated tags')}<input value={version.tags.join(', ')} onChange={e => setVersion({ ...version, tags: e.target.value.split(',').map(s => s.trim()) })} /></label><label>{tr(en, 'Прогрессия', 'Progression')}<select value={version.progression.mode} onChange={e => setVersion({ ...version, progression: { ...version.progression, mode: e.target.value as ProgramVersion['progression']['mode'] } })}><option value="manual">{tr(en, 'Вручную', 'Manual')}</option><option value="step">{tr(en, 'Фиксированный шаг', 'Fixed increment')}</option><option value="top-reps">{tr(en, 'При верхней границе повторов', 'When upper rep target is met')}</option></select></label><NumberField key={props.settings.weightUnit} label={`${tr(en, 'Шаг веса', 'Load increment')} (${props.settings.weightUnit})`} value={trainingWeightFromKg(version.progression.stepKg, props.settings.weightUnit)} max={trainingWeightFromKg(100, props.settings.weightUnit)} onChange={value => setVersion({ ...version, progression: { ...version.progression, stepKg: value === null ? 0 : trainingWeightToKg(value, props.settings.weightUnit) } })} /></div><p className="physis-muted">{tr(en, 'Правило даёт рекомендацию после выполненных рабочих подходов. Изменения применяются только по вашему решению в новой версии.', 'The rule suggests a change after completed work sets. Apply it yourself in a new version.')}</p></details>
    <CycleLoadDesigner version={version} weightUnit={props.settings.weightUnit} onApply={next=>{setVersion(next);setSelectedDay(next.mesocycles[0].microcycles[0].days[0].id);}} />
    <CyclePlanTable version={version} weightUnit={props.settings.weightUnit} onSelect={setSelectedDay} />
    <div className="physis-row"><h3>{tr(en, 'Структура цикла', 'Cycle structure')} · {programDuration(version)} {tr(en, 'дней', 'days')}</h3><button type="button" onClick={() => { const meso = newMesocycle(); meso.microcycles = Array.from({ length: 3 }, () => newMicrocycle(8)); const other = copyMeso(meso); setVersion({ ...version, mesocycles: [meso, other] }); setSelectedDay(meso.microcycles[0].days[0].id); }}>{tr(en, 'Пустая структура 2 × 3 × 8', 'Empty structure 2 × 3 × 8')}</button></div>
    {version.mesocycles.map((meso, mi) => {
      const updateMeso = (next: typeof meso) => setVersion({ ...version, mesocycles: version.mesocycles.map((m, i) => i === mi ? next : m) });
      return <details key={meso.id} className="physis-training-cycle" open={version.mesocycles.length === 1 ? true : undefined}><summary>{meso.name || `${tr(en, 'Мезоцикл', 'Mesocycle')} ${mi + 1}`} · {meso.repeats}×{meso.deload ? ` · ${tr(en, 'разгрузка', 'deload')}` : ''}</summary><div className="physis-form"><label>{tr(en, 'Название мезоцикла', 'Mesocycle name')}<input value={meso.name} onChange={e => updateMeso({ ...meso, name: e.target.value })} /></label><NumberField label={tr(en, 'Повторы мезоцикла', 'Mesocycle repeats')} value={meso.repeats} min={1} max={100} onChange={repeats => { if (repeats && Number.isInteger(repeats)) updateMeso({ ...meso, repeats }); }} /></div><label><input type="checkbox" checked={meso.deload} onChange={e => updateMeso({ ...meso, deload: e.target.checked })} />{tr(en, 'Разгрузочный этап (нагрузки задаются вручную)', 'Deload stage (configure loads manually)')}</label><label>{tr(en, 'Заметка мезоцикла', 'Mesocycle note')}<textarea value={meso.notes} onChange={e => updateMeso({ ...meso, notes: e.target.value })} /></label><div className="physis-actions"><Reorder index={mi} length={version.mesocycles.length} label={tr(en, 'Переставить мезоцикл', 'Reorder mesocycle')} onMove={delta => setVersion({ ...version, mesocycles: reorder(version.mesocycles, mi, delta) })} /><button type="button" onClick={() => setVersion({ ...version, mesocycles: [...version.mesocycles.slice(0, mi + 1), copyMeso(meso), ...version.mesocycles.slice(mi + 1)] })}>{tr(en, 'Копировать мезоцикл', 'Copy mesocycle')}</button><button type="button" disabled={version.mesocycles.length === 1} onClick={() => setVersion({ ...version, mesocycles: version.mesocycles.filter(m => m.id !== meso.id) })}>{tr(en, 'Удалить мезоцикл', 'Remove mesocycle')}</button></div>
        {meso.microcycles.map((micro, ci) => {
          const updateMicro = (next: typeof micro) => updateMeso({ ...meso, microcycles: meso.microcycles.map((c, i) => i === ci ? next : c) });
          return <div key={micro.id} className="physis-training-micro"><h4>{micro.name || `${tr(en, 'Микроцикл', 'Microcycle')} ${ci + 1}`} · {micro.days.length} {tr(en, 'дней', 'days')} × {micro.repeats}</h4><div className="physis-form"><label>{tr(en, 'Название микроцикла', 'Microcycle name')}<input value={micro.name} onChange={e => updateMicro({ ...micro, name: e.target.value })} /></label><NumberField label={tr(en, 'Повторы микроцикла', 'Microcycle repeats')} value={micro.repeats} min={1} max={100} onChange={repeats => { if (repeats && Number.isInteger(repeats)) updateMicro({ ...micro, repeats }); }} /></div><label>{tr(en, 'Заметка микроцикла', 'Microcycle note')}<textarea value={micro.notes} onChange={e => updateMicro({ ...micro, notes: e.target.value })} /></label><div className="physis-actions"><Reorder index={ci} length={meso.microcycles.length} label={tr(en, 'Переставить микроцикл', 'Reorder microcycle')} onMove={delta => updateMeso({ ...meso, microcycles: reorder(meso.microcycles, ci, delta) })} /><button type="button" onClick={() => updateMeso({ ...meso, microcycles: [...meso.microcycles.slice(0, ci + 1), copyMicro(micro), ...meso.microcycles.slice(ci + 1)] })}>{tr(en, 'Копировать микроцикл', 'Copy microcycle')}</button><button type="button" disabled={meso.microcycles.length === 1} onClick={() => updateMeso({ ...meso, microcycles: meso.microcycles.filter(c => c.id !== micro.id) })}>{tr(en, 'Удалить микроцикл', 'Remove microcycle')}</button></div><ol className="physis-training-days">{micro.days.map((day, di) => <li key={day.id}><button type="button" className={day.id === selectedDay ? 'physis-primary' : ''} aria-pressed={day.id === selectedDay} onClick={() => setSelectedDay(day.id)}>{di + 1}. {day.name || tr(en, day.kind === 'rest' ? 'Отдых' : 'Тренировка', day.kind === 'rest' ? 'Rest' : 'Workout')}</button><Reorder index={di} length={micro.days.length} label={`${tr(en, 'Переставить день', 'Reorder day')} ${di + 1}`} onMove={delta => updateMicro({ ...micro, days: reorder(micro.days, di, delta) })} /><button type="button" onClick={() => updateMicro({ ...micro, days: [...micro.days.slice(0, di + 1), copyDay(day), ...micro.days.slice(di + 1)] })}>{tr(en, 'Копия', 'Copy')}</button><button type="button" disabled={micro.days.length === 1} onClick={() => updateMicro({ ...micro, days: micro.days.filter(d => d.id !== day.id) })}>{tr(en, 'Удалить', 'Remove')}</button></li>)}</ol><div className="physis-actions"><button type="button" onClick={() => { const day = newCycleDay(); updateMicro({ ...micro, days: [...micro.days, day] }); setSelectedDay(day.id); }}>{tr(en, 'Добавить тренировочный день', 'Add workout day')}</button><button type="button" onClick={() => updateMicro({ ...micro, days: [...micro.days, newCycleDay('rest')] })}>{tr(en, 'Добавить отдых', 'Add rest')}</button></div></div>;
        })}<div className="physis-form"><NumberField label={tr(en, 'Длина нового микроцикла', 'New microcycle length')} value={length} min={1} max={100} onChange={setLength} /><button type="button" disabled={!length || !Number.isInteger(length)} onClick={() => updateMeso({ ...meso, microcycles: [...meso.microcycles, newMicrocycle(length ?? 8)] })}>{tr(en, 'Добавить микроцикл', 'Add microcycle')}</button></div>
      </details>;
    })}<button type="button" onClick={() => setVersion({ ...version, mesocycles: [...version.mesocycles, newMesocycle()] })}>{tr(en, 'Добавить мезоцикл', 'Add mesocycle')}</button>
    {selected && <><h3>{tr(en, 'Выбранный день', 'Selected day')}</h3><DayEditor key={selected.id} props={props} day={selected} update={value => setDay(selected.id, value)} /></>}
    <div className="physis-actions physis-training-primary-actions"><button type="submit" className="physis-primary" disabled={action.busy}>{isExisting ? tr(en, 'Сохранить новую версию', 'Save new version') : tr(en, 'Сохранить программу', 'Save program')}</button></div>
  </form></section>;
}

function AssignmentCreator({ program, props, onClose }: { program: PhysisRecord<TrainingProgram>; props: PhysisFeatureProps; onClose: () => void }) {
  const en = props.language === 'en'; const action = useAction();
  const [start, setStart] = useState(todayCivilDate(props.context)); const [mode, setMode] = useState<'fixed' | 'next'>('fixed'); const [advance, setAdvance] = useState<'complete' | 'finished'>('finished');
  const [versionId, setVersionId] = useState(program.data.versions.at(-1)!.id);
  const [preview, setPreview] = useState<TrainingAssignment | null>(null);
  const pendingRecord = useRef<PhysisRecord<TrainingAssignment> | null>(null);
  const version = program.data.versions.find(v => v.id === versionId)!;
  const otherPlans = physisRecords<TrainingAssignment>(props.store, 'assignment').filter(a => !a.data.paused).flatMap(a => a.data.scheduled.filter(s => s.snapshot.kind === 'workout' && s.state !== 'skipped'));
  const overlaps = preview?.scheduled.filter(s => s.snapshot.kind === 'workout' && otherPlans.some(p => p.day === s.day)).length ?? 0;
  return <section className="physis-panel"><div className="physis-row"><h3>{tr(en, 'Назначить программу', 'Assign program')}: {program.data.name}</h3><button type="button" onClick={onClose}>{tr(en, 'Закрыть', 'Close')}</button></div><ErrorMessage error={action.error} /><div className="physis-form"><label>{tr(en, 'Версия', 'Version')}<select value={versionId} onChange={e => { setVersionId(e.target.value); setPreview(null); }}>{program.data.versions.map(v => <option key={v.id} value={v.id}>v{v.version} · {programDuration(v)} {tr(en, 'дней', 'days')}</option>)}</select></label><label>{tr(en, 'Дата начала', 'Start date')}<CalendarDatePicker value={start} mode={props.settings.inputCalendarMode} calculationContext={props.context} ariaLabel={tr(en, 'Дата начала программы', 'Program start date')} onChange={v => { setStart(v); setPreview(null); }} /></label><label>{tr(en, 'Режим', 'Mode')}<select value={mode} onChange={e => { setMode(e.target.value as 'fixed' | 'next'); setPreview(null); }}><option value="fixed">{tr(en, 'По фиксированным датам', 'Fixed dates')}</option><option value="next">{tr(en, 'Следующая тренировка', 'Next workout')}</option></select></label>{mode === 'next' && <label>{tr(en, 'Продвигать последовательность', 'Advance sequence')}<select value={advance} onChange={e => { setAdvance(e.target.value as 'complete' | 'finished'); setPreview(null); }}><option value="finished">{tr(en, 'После полного или частичного завершения', 'After complete or partial finish')}</option><option value="complete">{tr(en, 'Только после полного выполнения', 'Only after full completion')}</option></select></label>}</div><p className="physis-muted">{mode === 'next' ? tr(en, 'Даты служат ориентиром. Следующее незавершённое занятие доступно последовательно; отдых не требует отметки. Пропуск — отдельное решение; даты не сдвигаются автоматически.', 'Dates are projections. The next unfinished workout is available in order; rest needs no check-off. Skipping is explicit; dates never shift automatically.') : tr(en, 'Занятия привязаны к датам. Пропуск не сдвигает будущие занятия.', 'Workouts have fixed dates. Skipping does not shift later workouts.')}</p><button type="button" disabled={!start} onClick={() => { try { setPreview(assignProgram(program.id, version, start, mode, advance)); action.setError(''); } catch (e) { action.setError(e instanceof Error ? e.message : 'Ошибка программы'); } }}>{tr(en, 'Предпросмотр назначения', 'Preview assignment')}</button>{preview && <><p>{preview.scheduled.length} {tr(en, 'дней', 'days')} · {formatCalendarDateValue(preview.scheduled[0].day, props.settings.calendarMode, false, props.context)} — {formatCalendarDateValue(preview.scheduled.at(-1)!.day, props.settings.calendarMode, false, props.context)}</p>{overlaps > 0 && <p className="physis-warning">{tr(en, 'Пересечений с другими программами', 'Overlaps with other programs')}: {overlaps}. {tr(en, 'Проверьте план; несколько занятий в день разрешены.', 'Review the plan; multiple sessions per day are allowed.')}</p>}<SchedulePreview assignment={preview} props={props} /><button type="button" className="physis-primary" disabled={action.busy} onClick={() => { void action.run(async () => { const record = pendingRecord.current ? editPhysisRecord(pendingRecord.current, preview) : newPhysisRecord('assignment', preview); pendingRecord.current = record; await props.store.save(record); onClose(); }); }}>{tr(en, 'Подтвердить назначение', 'Confirm assignment')}</button></>}</section>;
}
function SchedulePreview({ assignment, props }: { assignment: TrainingAssignment; props: PhysisFeatureProps }) {
  const en = props.language === 'en';
  return <details><summary>{tr(en, 'Все дни назначения', 'All scheduled days')}</summary><ol className="physis-training-schedule-preview">{assignment.scheduled.map(s => <li key={s.id}><time dateTime={s.day}>{formatCalendarDateValue(s.day, props.settings.calendarMode, false, props.context)}</time> · {s.snapshot.name || tr(en, s.snapshot.kind === 'rest' ? 'Отдых' : 'Тренировка', s.snapshot.kind === 'rest' ? 'Rest' : 'Workout')} · {s.micro}/{s.cycleDay}{s.movedFrom ? ` (${s.movedFrom} → ${s.day})` : ''}</li>)}</ol></details>;
}

function Programs(props: PhysisFeatureProps) {
  const creationDrafts = useRef(new TrainingCreationDrafts<TrainingProgram>()).current;
  const en = props.language === 'en'; const action = useAction();
  const [editing, setEditing] = useState<PhysisRecord<TrainingProgram> | null>(null);
  const [assigning, setAssigning] = useState<PhysisRecord<TrainingProgram> | null>(null);
  const [collection, setCollection] = useState<'personal' | 'alchemy'>('personal');
  const [archived, setArchived] = useState(false); const [query, setQuery] = useState('');
  const programs = physisRecords<TrainingProgram>(props.store, 'program').filter(p => p.data.collection === collection && p.data.archived === archived && `${p.data.name} ${p.data.versions.at(-1)?.goal ?? ''}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
  const create = () => { const program = newProgram(); program.collection = collection; setEditing(newPhysisRecord('program', program)); };
  if (editing) return <ProgramEditor key={editing.id} record={editing} props={props} onClose={() => setEditing(null)} />;
  if (assigning) return <AssignmentCreator key={assigning.id} program={assigning} props={props} onClose={() => setAssigning(null)} />;
  return <div className="physis-programs-layout">
    <section className="physis-panel physis-program-library">
      <header className="physis-program-heading"><div><h2>{tr(en, 'Программы тренировок', 'Training programs')}</h2><p className="physis-muted">{tr(en, 'Ваши планы, циклы нагрузки и версии в одном месте.', 'Your plans, load cycles and versions in one place.')}</p></div><button type="button" className="physis-primary physis-program-create" onClick={create}><ExperimentalIcon name="plus" />{tr(en, 'Создать программу', 'Create program')}</button></header>
      <ErrorMessage error={action.error} />
      <div className="physis-program-toolbar"><nav className="physis-tabs" aria-label={tr(en, 'Коллекции программ', 'Program collections')}><button type="button" aria-current={collection === 'personal' ? 'page' : undefined} onClick={() => setCollection('personal')}>{tr(en, 'Мои программы', 'My programs')}</button><button type="button" aria-current={collection === 'alchemy' ? 'page' : undefined} onClick={() => setCollection('alchemy')}>{tr(en, 'Алхимический фитнес', 'Alchemical fitness')}</button></nav><IconActionButton icon="archive" label={tr(en, 'Показать архив программ', 'Show archived programs')} aria-pressed={archived} onClick={() => setArchived(!archived)} /></div>
      <label className="physis-program-search">{tr(en, 'Поиск программ', 'Search programs')}<input type="search" value={query} onChange={event => setQuery(event.target.value)} /></label>
      {collection === 'alchemy' && <p className="physis-muted">{tr(en, 'Коллекция ваших авторских шаблонов. Названия этапов, символы и цели задаёте вы; готовая методика пока не предоставлена.', 'Your collection of authored templates. Define your own stages, symbols and goals; no completed methodology has been supplied.')}</p>}
      {!programs.length && <div className="physis-program-empty"><ExperimentalIcon name={archived ? 'archive' : 'calendar'} /><div><h3>{query.trim() ? tr(en, 'Программы не найдены', 'No matching programs') : archived ? tr(en, 'Архив пока пуст', 'The archive is empty') : tr(en, 'Создайте свой первый план', 'Create your first plan')}</h3><p>{query.trim() ? tr(en, 'Измените запрос или выберите другую коллекцию.', 'Change your search or choose another collection.') : archived ? tr(en, 'Здесь хранятся программы, которые вы отправили в архив.', 'Programs you archive will appear here.') : tr(en, 'Соберите упражнения, настройте подходы и время, затем выберите дату начала.', 'Choose exercises, set repetitions and timing, then choose a start date.')}</p>{!archived && !query.trim() && <ol><li>{tr(en, 'Создайте программу', 'Create a program')}</li><li>{tr(en, 'Запланируйте занятия', 'Plan workouts')}</li><li>{tr(en, 'Назначьте дату начала', 'Choose a start date')}</li></ol>}</div></div>}
      <div className="physis-program-list">{programs.map(program => { const version = program.data.versions.at(-1)!; return <article key={program.id} className="physis-program-item"><div className="physis-program-item-copy"><h3>{program.data.name}</h3>{version.goal && <p>{version.goal}</p>}<p className="physis-muted">{programDuration(version)} {tr(en, 'дней', 'days')} · {version.mesocycles.length} {tr(en, 'мезоцикл(а)', 'mesocycle(s)')} · v{version.version}</p></div><div className="physis-actions"><button type="button" className="physis-primary" disabled={program.data.archived} onClick={() => setAssigning(program)}>{tr(en, 'Назначить с даты', 'Assign from date')}</button><IconActionButton icon="edit" label={tr(en, 'Создать новую версию', 'Create new version')} onClick={() => setEditing(program)} /><IconActionButton icon="copy" label={tr(en, 'Дублировать программу', 'Duplicate program')} disabled={action.busy} onClick={() => { void action.run(async () => { await creationDrafts.save(program.id, () => { const copy = clone(program.data); copy.name += ` — ${tr(en, 'копия', 'copy')}`; copy.archived = false; copy.versions = [{ ...clone(version), id: crypto.randomUUID(), version: 1, createdAt: new Date().toISOString(), name: copy.name }]; return newPhysisRecord('program', copy); }, props.store); }); }} /><IconActionButton icon={program.data.archived ? 'undo' : 'archive'} label={program.data.archived ? tr(en, 'Вернуть программу из архива', 'Restore program from archive') : tr(en, 'Отправить программу в архив', 'Archive program')} disabled={action.busy} onClick={() => { void action.run(async () => { await props.store.save(editPhysisRecord(program, { ...program.data, archived: !program.data.archived })); }); }} /></div></article>; })}</div>
    </section>
    <section className="physis-panel physis-program-assignments"><Assignments props={props} /></section>
  </div>;
}

function Assignments({ props }: { props: PhysisFeatureProps }) {
  const en = props.language === 'en'; const action = useAction();
  const assignments = physisRecords<TrainingAssignment>(props.store, 'assignment'); const sessions = physisRecords<TrainingSession>(props.store, 'session'); const programs = physisRecords<TrainingProgram>(props.store, 'program');
  const [from, setFrom] = useState(todayCivilDate(props.context));
  const [pending, setPending] = useState<{ record: PhysisRecord<TrainingAssignment>; next: TrainingAssignment } | null>(null);
  return <div><h2>{tr(en, 'Назначенные циклы', 'Assigned cycles')}</h2><ErrorMessage error={action.error} />{!assignments.length && <p className="physis-empty">{tr(en, 'Назначения появятся после выбора программы и даты начала.', 'Assignments appear after choosing a program and start date.')}</p>}{assignments.map(a => {
    const score = completionScore(a, sessions, todayCivilDate(props.context)); const program = programs.find(p => p.id === a.data.programId); const latest = program?.data.versions.at(-1);
    return <details key={a.id} className="physis-training-program"><summary>{a.data.snapshot.name} · v{a.data.snapshot.version} · {a.data.paused ? tr(en, 'Пауза', 'Paused') : tr(en, 'Активна', 'Active')}</summary><p>{a.data.mode === 'fixed' ? tr(en, 'Фиксированные даты', 'Fixed dates') : tr(en, 'Следующая тренировка', 'Next workout')} · {score.percent ?? '—'}% ({shortNumber(score.earned)}/{score.due})</p><p>{tr(en, 'Начало', 'Start')}: {formatCalendarDateValue(a.data.startDay, props.settings.calendarMode, true, props.context)}</p><button type="button" disabled={action.busy} onClick={() => { void action.run(async () => { await props.store.save(editPhysisRecord(a, { ...a.data, paused: !a.data.paused })); }); }}>{a.data.paused ? tr(en, 'Продолжить программу', 'Resume program') : tr(en, 'Приостановить программу', 'Pause program')}</button><p className="physis-muted">{tr(en, 'Пауза не сдвигает даты. Перенос отдельного дня или будущего хвоста доступен в календаре.', 'Pausing never shifts dates. Move a day or the future sequence from the calendar.')}</p>{latest && latest.id !== a.data.snapshot.id && <div className="physis-form"><label>{tr(en, 'Обновить будущий план с даты', 'Update future plan from date')}<CalendarDatePicker value={from} mode={props.settings.inputCalendarMode} calculationContext={props.context} ariaLabel={tr(en, 'Дата применения новой версии', 'Apply new version from date')} onChange={setFrom} /></label><button type="button" disabled={!from} onClick={() => { try { const locked = new Set(sessions.filter(s => s.data.assignmentId === a.id).map(s => s.data.scheduledId!)); setPending({ record: a, next: applyVersionFrom(a.data, latest, from, locked) }); } catch (e) { action.setError(e instanceof Error ? e.message : 'Ошибка'); } }}>{tr(en, 'Предпросмотр новой версии', 'Preview new version')} v{latest.version}</button></div>}<SchedulePreview assignment={a.data} props={props} /><div className="physis-training-progress"><h4>{tr(en, 'Прогресс этапов', 'Stage progress')}</h4>{[...new Set(a.data.scheduled.map(s => s.meso))].map(meso => { const items = a.data.scheduled.filter(s => s.meso === meso); const filtered = { ...a, data: { ...a.data, scheduled: items } }; const result = completionScore(filtered, sessions, todayCivilDate(props.context)); return <div key={meso}><strong>{tr(en, 'Мезоцикл', 'Mesocycle')} {meso}: {result.percent ?? '—'}%</strong>{[...new Set(items.map(s => s.micro))].map(micro => { const cycle = completionScore({ ...a, data: { ...a.data, scheduled: items.filter(s => s.micro === micro) } }, sessions, todayCivilDate(props.context)); return <p key={micro}>{tr(en, 'Микроцикл', 'Microcycle')} {micro}: {cycle.percent ?? '—'}%</p>; })}</div>; })}</div></details>;
  })}{pending && <div className="physis-training-editor"><h4>{tr(en, 'Проверка будущего плана', 'Review future plan')}</h4><p>{tr(en, 'Начатые и завершённые занятия сохраняют снимок. Дни до выбранной даты не меняются.', 'Started and completed workouts retain their snapshots. Earlier days remain unchanged.')}</p><SchedulePreview assignment={pending.next} props={props} /><div className="physis-actions"><button type="button" className="physis-primary" disabled={action.busy} onClick={() => { void action.run(async () => { await props.store.save(editPhysisRecord(pending.record, pending.next)); setPending(null); }); }}>{tr(en, 'Применить к будущему плану', 'Apply to future plan')}</button><button type="button" onClick={() => setPending(null)}>{tr(en, 'Отмена', 'Cancel')}</button></div></div>}</div>;
}

function MoveWorkout({ assignment, item, props, onClose }: { assignment: PhysisRecord<TrainingAssignment>; item: ScheduledWorkout; props: PhysisFeatureProps; onClose: () => void }) {
  const en = props.language === 'en'; const action = useAction();
  const [day, setDay] = useState(addCivilDays(item.day, 1)); const [scope, setScope] = useState<'one' | 'tail'>('one'); const [preview, setPreview] = useState<TrainingAssignment | null>(null);
  const sessions = physisRecords<TrainingSession>(props.store, 'session');
  const locked = new Set(sessions.filter(s => s.data.assignmentId === assignment.id).map(s => s.data.scheduledId!));
  const changed = preview?.scheduled.filter(s => assignment.data.scheduled.find(old => old.id === s.id)?.day !== s.day) ?? [];
  const otherDays = physisRecords<TrainingAssignment>(props.store, 'assignment').filter(a => a.id !== assignment.id && !a.data.paused).flatMap(a => a.data.scheduled.filter(s => s.snapshot.kind === 'workout' && s.state !== 'skipped').map(s => s.day));
  const conflict = changed.some(s => s.snapshot.kind === 'workout' && otherDays.includes(s.day));
  return <div className="physis-training-editor"><h4>{tr(en, 'Перенос занятия', 'Move workout')}</h4><ErrorMessage error={action.error} /><div className="physis-form"><label>{tr(en, 'Новая дата', 'New date')}<CalendarDatePicker value={day} mode={props.settings.inputCalendarMode} calculationContext={props.context} ariaLabel={tr(en, 'Новая дата тренировки', 'New workout date')} onChange={v => { setDay(v); setPreview(null); }} /></label><label>{tr(en, 'Область переноса', 'Move scope')}<select value={scope} onChange={e => { setScope(e.target.value as 'one' | 'tail'); setPreview(null); }}><option value="one">{tr(en, 'Только это занятие', 'This workout only')}</option><option value="tail">{tr(en, 'Это занятие и будущий хвост', 'This and later days')}</option></select></label></div><button type="button" disabled={!day} onClick={() => { try { setPreview(previewMove(assignment.data, item.id, day, scope, locked)); } catch (e) { action.setError(e instanceof Error ? e.message : 'Ошибка переноса'); } }}>{tr(en, 'Посмотреть изменения', 'Preview changes')}</button>{preview && <><p>{tr(en, 'Изменится дней', 'Days changed')}: {changed.length}. {tr(en, 'Начатые и пропущенные занятия не перемещаются.', 'Started and skipped workouts are not moved.')}</p>{conflict && <p className="physis-warning">{tr(en, 'Новая дата пересекается с другой программой.', 'A new date overlaps another program.')}</p>}<ol className="physis-training-schedule-preview">{changed.map(s => <li key={s.id}>{assignment.data.scheduled.find(old => old.id === s.id)?.day} → {s.day} · {s.snapshot.name || statusName(s.snapshot.kind === 'rest' ? 'rest' : 'planned', en)}</li>)}</ol><button type="button" className="physis-primary" disabled={action.busy || !changed.length} onClick={() => { void action.run(async () => { await props.store.save(editPhysisRecord(assignment, preview)); onClose(); }); }}>{tr(en, 'Подтвердить перенос', 'Confirm move')}</button></>}<button type="button" onClick={onClose}>{tr(en, 'Отмена', 'Cancel')}</button></div>;
}

function DayLog({ day, props, onOpen, onStart }: { day: string; props: PhysisFeatureProps; onOpen: (record: PhysisRecord<TrainingSession>) => void; onStart: (day: string, scheduled?: ScheduledWorkout, assignment?: PhysisRecord<TrainingAssignment>) => void }) {
  const en = props.language === 'en'; const action = useAction();
  const sessions = physisRecords<TrainingSession>(props.store, 'session');
  const assignments = physisRecords<TrainingAssignment>(props.store, 'assignment');
  const [moving, setMoving] = useState<{ assignment: PhysisRecord<TrainingAssignment>; item: ScheduledWorkout } | null>(null);
  const daySessions = sessions.filter(s => s.data.localDay === day).sort((a, b) => a.data.startedAt.localeCompare(b.data.startedAt));
  const scheduled = assignments.flatMap(a => a.data.scheduled.filter(s => s.day === day).map(item => ({ assignment: a, item })));
  const movedAway = assignments.flatMap(a => a.data.scheduled.filter(s => s.movedFrom === day && s.day !== day).map(item => ({ assignment: a, item })));
  return <section className="physis-training-day-log"><h3>{formatCalendarDateValue(day, props.settings.calendarMode, true, props.context)}</h3><ErrorMessage error={action.error} />
    {!scheduled.length && !daySessions.length && <p className="physis-empty">{tr(en, 'На этот день нет занятий. Составьте и назначьте программу в «Мои тренировки».', 'No workouts on this day. Create and assign a program in My workouts.')}</p>}
    {scheduled.map(({ assignment, item }) => { const status = scheduleStatus(item, sessions, assignment.id); const issue = plannedWorkoutError(assignment, item.id, sessions, day); const related = sessions.filter(s => s.data.assignmentId === assignment.id && s.data.scheduledId === item.id); const current = related.find(s => !s.data.endedAt) ?? related.at(-1); return <article key={item.id} className="physis-training-schedule-item"><div className="physis-row"><h4>{item.snapshot.name || (item.snapshot.kind === 'rest' ? tr(en, 'Отдых', 'Rest') : assignment.data.snapshot.name)}</h4><span className="physis-status">{statusName(status, en)}</span></div><p className="physis-muted">{assignment.data.snapshot.name} · {tr(en, 'Микроцикл', 'Microcycle')} {item.micro} · {tr(en, 'День', 'Day')} {item.cycleDay}{assignment.data.paused ? ` · ${tr(en, 'Программа приостановлена', 'Program paused')}` : ''}</p>{item.movedFrom && <p>{tr(en, 'Перенесено с', 'Moved from')} {formatCalendarDateValue(item.movedFrom, props.settings.calendarMode, false, props.context)}</p>}{item.snapshot.kind === 'workout' && <div className="physis-actions">{current ? <button type="button" onClick={() => onOpen(current)}>{current.data.endedAt ? tr(en, 'Открыть результат', 'Open result') : tr(en, 'Продолжить тренировку', 'Continue workout')}</button> : <button type="button" className="physis-primary" disabled={!!issue || day > todayCivilDate(props.context)} title={issue ?? undefined} onClick={() => onStart(day, item, assignment)}>{tr(en, 'Начать по плану', 'Start from plan')}</button>}{issue && !current && item.state !== 'skipped' && <p className="physis-muted">{issue}</p>}{status === 'partial' && assignment.data.advanceOn === 'complete' && <button type="button" disabled={!!issue || day > todayCivilDate(props.context)} onClick={() => onStart(day, item, assignment)}>{tr(en, 'Новая попытка занятия', 'New workout attempt')}</button>}{!related.length && <><button type="button" onClick={() => setMoving({ assignment, item })}>{tr(en, 'Перенести', 'Move')}</button><button type="button" disabled={action.busy} onClick={() => { void action.run(async () => { await props.store.save(editPhysisRecord(assignment, { ...assignment.data, scheduled: assignment.data.scheduled.map(s => s.id === item.id ? { ...s, state: s.state === 'skipped' ? 'planned' : 'skipped' } : s) })); }); }}>{item.state === 'skipped' ? tr(en, 'Вернуть в план', 'Restore plan') : tr(en, 'Отметить пропуск', 'Mark skipped')}</button></>}</div>}</article>; })}
    {movedAway.map(({ item }) => <p key={`moved:${item.id}`} className="physis-muted">{item.snapshot.name || tr(en, 'Тренировка', 'Workout')}: {tr(en, 'перенесено на', 'moved to')} {formatCalendarDateValue(item.day, props.settings.calendarMode, false, props.context)} · {tr(en, 'не считается пропуском', 'not counted as missed')}</p>)}
    {daySessions.length > 0 && <><h4>{tr(en, 'Фактические занятия', 'Recorded sessions')} · {daySessions.length}</h4>{daySessions.map(record => { const summary = sessionSummary(record.data); return <div className="physis-training-schedule-item" key={record.id}><button type="button" onClick={() => onOpen(record)}>{record.data.name || tr(en, 'Тренировка', 'Workout')} · {statusName(record.data.status, en)}</button><p className="physis-muted">{summary.completedSets}/{summary.sets} {tr(en, 'подходов', 'sets')} · {Math.round(summary.seconds / 60)} {tr(en, 'мин', 'min')}{record.data.editedAt ? ` · ${tr(en, 'Исправлено', 'Edited')}` : ''}</p></div>; })}</>}
    {moving && <MoveWorkout key={moving.item.id} {...moving} props={props} onClose={() => setMoving(null)} />}
  </section>;
}

function TrainingCalendar({ props, onOpen, onStart }: { props: PhysisFeatureProps; onOpen: (record: PhysisRecord<TrainingSession>) => void; onStart: (day: string, scheduled?: ScheduledWorkout, assignment?: PhysisRecord<TrainingAssignment>) => void }) {
  const en = props.language === 'en'; const today = todayCivilDate(props.context);
  const [day, setDay] = useState(today); const mode = props.settings.calendarMode;
  const range = calendarMonthRange(day, mode, props.context); const days: string[] = [];
  for (let date = range.start; date <= range.end; date = addCivilDays(date, 1)) days.push(date);
  const sessions = physisRecords<TrainingSession>(props.store, 'session'); const assignments = physisRecords<TrainingAssignment>(props.store, 'assignment');
  const due = assignments.reduce((n, a) => n + completionScore(a, sessions, today, range).due, 0); const earned = assignments.reduce((n, a) => n + completionScore(a, sessions, today, range).earned, 0);
  const calendarProps = { ...props, settings: { ...props.settings, calendarMode: mode } };
  return <div className="physis-training-control-page"><div className="physis-form"><label>{tr(en, 'Перейти к дню', 'Go to day')}<CalendarDatePicker value={day} mode={mode} calculationContext={props.context} ariaLabel={tr(en, 'День календаря тренировок', 'Workout calendar day')} onChange={value => { if (value) setDay(value); }} /></label></div><div className="physis-row"><button type="button" onClick={() => setDay(addCivilDays(range.start, -1))} aria-label={tr(en, 'Предыдущий месяц', 'Previous month')}>←</button><h3>{formatCalendarMonthValue(day, mode, props.context)}</h3><button type="button" onClick={() => setDay(addCivilDays(range.end, 1))} aria-label={tr(en, 'Следующий месяц', 'Next month')}>→</button><button type="button" onClick={() => setDay(today)}>{tr(en, 'Этот месяц', 'This month')}</button></div><p>{tr(en, 'Фактических сессий в месяце', 'Recorded sessions this month')}: {sessions.filter(s => s.data.localDay >= range.start && s.data.localDay <= range.end).length} · {tr(en, 'Выполнение плана', 'Plan completion')}: {due ? `${Math.round(earned / due * 100)}%` : '—'}</p><div className="physis-training-month">{days.map(date => {
    const facts = sessions.filter(s => s.data.localDay === date); const plan = assignments.flatMap(a => a.data.scheduled.filter(s => s.day === date).map(item => ({ item, assignment: a })));
    const states = [...new Set([...facts.map(s => s.data.status), ...plan.map(p => scheduleStatus(p.item, sessions, p.assignment.id))])];
    return <button type="button" key={date} aria-pressed={date === day} aria-current={date === today ? 'date' : undefined} className={date === day ? 'physis-primary' : ''} onClick={() => setDay(date)}><time dateTime={date}>{formatCalendarDateValue(date, mode, false, props.context)}</time>{facts.length > 0 && <strong>{facts.length} {tr(en, 'сесс.', 'sessions')}</strong>}{states.map(state => <span key={state} className={`physis-training-day-status is-${state}`}>{statusName(state, en)}</span>)}</button>;
  })}</div><p className="physis-muted">{tr(en, 'Процент = выполненные эквиваленты / наступившие тренировочные дни. Частичное занятие: отмеченные подходы / плановые, максимум 1. Отдых, будущие даты и исходный день переноса исключены; явный пропуск даёт 0. Несколько попыток одного плана дают максимум одного дня.', 'Completion = completed equivalents / due workout days. Partial: checked sets / planned sets, capped at 1. Rest, future dates and the original moved day are excluded; explicit skips score 0. Multiple attempts count at most one planned day.')}</p><DayLog day={day} props={calendarProps} onOpen={onOpen} onStart={onStart} /></div>;
}

function TrainingStatistics(props: PhysisFeatureProps) {
  const en = props.language === 'en'; const today = todayCivilDate(props.context);
  const [start, setStart] = useState(calendarMonthRange(today, props.settings.calendarMode, props.context).start); const [end, setEnd] = useState(today);
  const sessions = physisRecords<TrainingSession>(props.store, 'session').filter(s => !!s.data.endedAt && s.data.localDay >= start && s.data.localDay <= end).sort((a, b) => a.data.startedAt.localeCompare(b.data.startedAt));
  const totals = sessions.reduce((sum, s) => { const value = sessionSummary(s.data); return { count: sum.count + 1, sets: sum.sets + value.completedSets, seconds: sum.seconds + value.seconds, volume: sum.volume + value.volumeKg, distance: sum.distance + value.distanceKm }; }, { count: 0, sets: 0, seconds: 0, volume: 0, distance: 0 });
  const rows = new Map<string, { name: string; convention: WeightMode; side: string; count: number; volume: number; first: number | null; last: number | null; best: number | null; seconds: number; distance: number }>();
  for (const session of sessions) for (const ex of session.data.exercises) for (const set of ex.sets.filter(s => s.completed && s.kind === 'work')) {
    const key = `${comparableKey(ex)}|${set.side}`; const e1rm = estimatedOneRepMax(ex, set);
    const row = rows.get(key) ?? { name: exerciseDisplayName(ex.snapshot, en), convention: ex.snapshot.weightMode, side: set.side, count: 0, volume: 0, first: null, last: null, best: null, seconds: 0, distance: 0 };
    row.count++; row.volume += setVolume(ex, set); row.seconds += set.seconds ?? 0; row.distance += set.distanceKm ?? 0;
    if (e1rm !== null) { row.first ??= e1rm; row.last = e1rm; row.best = Math.max(row.best ?? 0, e1rm); }
    rows.set(key, row);
  }
  return <div className="physis-training-control-page"><div className="physis-form"><label>{tr(en, 'С даты', 'From')}<CalendarDatePicker value={start} mode={props.settings.inputCalendarMode} calculationContext={props.context} ariaLabel={tr(en, 'Начало периода статистики', 'Statistics start')} onChange={v => { if (v) setStart(v); }} /></label><label>{tr(en, 'По дату', 'Until')}<CalendarDatePicker value={end} mode={props.settings.inputCalendarMode} calculationContext={props.context} ariaLabel={tr(en, 'Конец периода статистики', 'Statistics end')} onChange={v => { if (v) setEnd(v); }} /></label></div>{start > end && <p className="physis-warning">{tr(en, 'Дата начала позже окончания.', 'Start date is after end date.')}</p>}{!sessions.length ? <p className="physis-empty">{tr(en, 'В этом периоде ещё нет завершённых тренировок. Статистика появится после фиксации подходов.', 'No finished workouts in this period. Statistics appear after recording actual sets.')}</p> : <><p>{totals.count} {tr(en, 'занятий', 'workouts')} · {totals.sets} {tr(en, 'отмеченных подходов', 'completed sets')} · {Math.round(totals.seconds / 60)} {tr(en, 'мин', 'min')} · {shortNumber(trainingDistanceFromKm(totals.distance, props.settings.distanceUnit))} {props.settings.distanceUnit}</p><TrainingProgressCharts sessions={sessions} props={props} /><div className="physis-table-wrap"><table><caption>{tr(en, 'Сопоставимые упражнения и рабочие подходы', 'Comparable exercises and work sets')}</caption><thead><tr><th>{tr(en, 'Упражнение / учёт веса', 'Exercise / load convention')}</th><th>{tr(en, 'Подходы', 'Sets')}</th><th>{tr(en, 'Внешний объём', 'External volume')} ({props.settings.weightUnit}·{tr(en, 'повт.', 'reps')})</th><th>{tr(en, 'Лучший расчётный 1ПМ', 'Best estimated 1RM')} ({props.settings.weightUnit})</th><th>{tr(en, 'Последняя оценка / первая', 'Last estimate / first')} ({props.settings.weightUnit})</th></tr></thead><tbody>{[...rows.entries()].map(([key, row]) => <tr key={key}><th scope="row">{row.name}<small>{weightNames(en)[row.convention]} · {row.side}</small></th><td>{row.count}{row.seconds > 0 && <small>{row.seconds} s</small>}{row.distance > 0 && <small>{shortNumber(trainingDistanceFromKm(row.distance, props.settings.distanceUnit))} {props.settings.distanceUnit}</small>}</td><td>{row.convention === 'assisted' ? '—' : shortNumber(trainingWeightFromKg(row.volume, props.settings.weightUnit))}</td><td>{row.best === null ? '—' : shortNumber(trainingWeightFromKg(row.best, props.settings.weightUnit))}</td><td>{row.first === null || row.last === null ? '—' : `${shortNumber(trainingWeightFromKg(row.last, props.settings.weightUnit))} / ${shortNumber(trainingWeightFromKg(row.first, props.settings.weightUnit))}`}</td></tr>)}</tbody></table></div></>}<details><summary>{tr(en, 'Методика расчёта', 'Calculation methodology')}</summary><p>{tr(en, 'Объём внешнего веса: вес × повторы только отмеченных рабочих подходов. Вес одной гантели / на сторону умножается на 2 при записи обеих сторон. Масса тела не прибавляется, противовес исключён. Время и расстояние суммируются отдельно. Паузы вычитаются из длительности занятия.', 'External load volume: load × reps for checked work sets only. Per-dumbbell / per-side load is doubled when both sides are recorded. Body mass is never added; assistance is excluded. Time and distance are summed separately. Pauses are subtracted from duration.')}</p><p>{tr(en, 'Расчётный 1ПМ — оценка Эпли: вес × (1 + повторы / 30), только 1–10 повторов, без разминки, собственного веса и противовеса. Единица оценки совпадает с введённым способом учёта веса. Это не измеренный максимум и не рекомендация выполнять максимальный подъём. Сравнение разделено по упражнению, способу веса и стороне.', 'Estimated 1RM uses Epley: load × (1 + reps / 30), for 1–10 reps, excluding warm-up, bodyweight and assistance. The estimate follows the recorded load convention. This is not a measured maximum or a recommendation to attempt a maximal lift. Comparisons separate exercises, load conventions and sides.')}</p></details></div>;
}

export function PhysisTraining(props: PhysisFeatureProps & { page: 'today' | 'programs' | 'control' | 'exercises' }) {
  const creationDrafts = useRef(new TrainingCreationDrafts<TrainingSession>()).current;
  const en = props.language === 'en'; const action = useAction();
  const [tab, setTab] = useState<'calendar' | 'statistics'>('calendar');
  const [opened, setOpened] = useState<PhysisRecord<TrainingSession> | null>(null);
  const sessions = physisRecords<TrainingSession>(props.store, 'session');
  const assignments = physisRecords<TrainingAssignment>(props.store, 'assignment');
  const today = todayCivilDate(props.context);
  const active = sessions.filter(s => !s.data.endedAt);
  const next = assignments.flatMap(a => { const item = nextScheduled(a, sessions, today); return item ? [{ assignment: a, item }] : []; });
  const openSession = (record: PhysisRecord<TrainingSession>) => { creationDrafts.open(record.id); setOpened(record); };
  const onStart = (day: string, scheduled?: ScheduledWorkout, assignment?: PhysisRecord<TrainingAssignment>) => { void action.run(async () => {
    if (scheduled && assignment) { const existing = sessions.find(s => !s.data.endedAt && s.data.scheduledId === scheduled.id && s.data.assignmentId === assignment.id); if (existing) { openSession(existing); return; } }
    if (active.length) throw new Error(tr(en, 'Сначала завершите открытую тренировку.', 'Finish the open workout first.'));
    if (day > today) throw new Error(tr(en, 'Будущее занятие пока остаётся планом.', 'A future workout remains a plan.'));
    const intent = `${day}:${assignment?.id}:${scheduled?.id}`;
    const record = await creationDrafts.save(intent, () => {
      const data = startPlannedSession(day, props.settings.timeZone, scheduled?.id, assignment, sessions);
      if (day < today) { const time = resolveCalendarWallTime(day, '12:00', props.settings.timeZone).instant.toISOString(); data.startedAt = time; data.endedAt = time; data.status = 'partial'; }
      return newPhysisRecord('session', data);
    }, props.store);
    openSession(record);
  }); };
  if (props.page === 'exercises') return <ExerciseCatalog {...props} />;
  if (props.page === 'programs') return <Programs {...props} />;
  if (opened) return <SessionEditor key={opened.id} record={opened} props={props} onClose={() => setOpened(null)} />;
  return <div className="physis-training"><ErrorMessage error={action.error} />
    {props.page === 'today' ? <section className="physis-panel"><h2>{tr(en, 'Сегодня', 'Today')}</h2><p className="physis-muted">{formatCalendarDateValue(today, props.settings.calendarMode, true, props.context)}</p>
      {active.map(record => <div className="physis-training-schedule-item" key={record.id}><p>{record.data.name || tr(en, 'Открытая тренировка', 'Open workout')} · {formatCalendarDateValue(record.data.localDay, props.settings.calendarMode, false, props.context)}</p><button type="button" className="physis-primary" onClick={() => openSession(record)}>{tr(en, 'Продолжить тренировку', 'Continue workout')}</button></div>)}
      {next.filter(({item}) => item.day !== today).map(({assignment,item}) => { const issue = plannedWorkoutError(assignment,item.id,sessions,today); return <div key={item.id} className="physis-training-schedule-item"><h3>{item.snapshot.name || assignment.data.snapshot.name}</h3><p>{tr(en, 'Следующее занятие программы', 'Next program workout')}</p>{issue && <p>{issue}</p>}<button className="physis-primary" disabled={!!issue || action.busy || !!active.length} onClick={() => onStart(today,item,assignment)}>{tr(en, 'Начать по плану', 'Start from plan')}</button></div>; })}
      <DayLog day={today} props={props} onOpen={openSession} onStart={onStart} />
    </section> : <section className="physis-panel physis-training-control"><header className="physis-control-heading"><h2>{tab === 'calendar' ? tr(en, 'Календарь тренировок', 'Workout calendar') : tr(en, 'Статистика тренировок', 'Training statistics')}</h2><div className="shared-projects-switch physis-control-switch" role="group" aria-label={tr(en, 'Режим контроля выполнения', 'Training control view')}>{(['calendar', 'statistics'] as const).map((id, i) => <button type="button" key={id} aria-pressed={tab === id} onClick={() => setTab(id)}>{[tr(en, 'Календарь', 'Calendar'), tr(en, 'Статистика', 'Statistics')][i]}</button>)}</div></header><div className="physis-control-view" hidden={tab !== 'calendar'}><TrainingCalendar props={props} onOpen={openSession} onStart={onStart} /></div><div className="physis-control-view" hidden={tab !== 'statistics'}><TrainingStatistics {...props} /></div></section>}
  </div>;
}
